#include <iostream>
#include <set>
int main() {
    std::set<int> mySet;  // Red-black tree-based set
    auto result = mySet.insert(42);  // Inserts 42 if not present
    if (result.second) {
        std::cout << "Inserted at: " << *result.first << std::endl;  // Output: Inserted at: 42
    } else {
        std::cout << "Already exists at: " << *result.first << std::endl;  // Output: Already exists at: 42
    }
    return 0;
}
